"""Remove Nodes From Linked List — reverse, keep a running maximum, reverse back.

Walking from the right makes "is there a bigger value later?" a single
comparison against the maximum seen so far.

Time: O(n)   Space: O(1)
"""
if "ListNode" not in globals():
    class ListNode:
        def __init__(self, val=0, next=None):
            self.val = val
            self.next = next


class Solution:
    def removeNodes(self, head):
        def reverse(node):
            prev = None
            while node:
                node.next, prev, node = prev, node, node.next
            return prev

        node = reverse(head)
        best = 0
        kept = None
        while node:
            nxt = node.next
            if node.val >= best:
                best = node.val
                node.next = kept
                kept = node
            node = nxt
        return kept
